import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        # Edge case: no elements
        return
    # The numbers start from data[1] to data[n]
    first = int(data[1])
    last = int(data[1 + n - 1])
    total = first + last
    if total % 2 == 0:
        print("Even")
    else:
        print("Odd")

if __name__ == "__main__":
    main()
